                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ["json_info", "results"])).match() }
            )
        }

    }

    test("sarscov2 - single_end multiple files") {

        when {
            process {
                """
                input[0] = channel.of([
                    [ id:'test', single_end: true ], // meta map
